 const [search,setSearch]=useState("");const [categoryFilter,setCategoryFilter]=useState("");const [brandFilter,setBrandFilter]=useState("");const [sortBy,setSortBy]=useState<"name"|"code"|"updated_at">("updated_at");const [sortOrder,setSortOrder]=useState<"asc"|"desc">("desc");const [productPage,setProductPage]=useState(1);const [productTotal,setProductTotal]=useState(0);const [categoryCode,setCategoryCode]=useState("");const [categoryName,setCategoryName]=useState("");const [brandName,setBrandName]=useState("");const [unitCode,setUnitCode]=useState("");const [unitName,setUnitName]=useState("");const [selectedCategory,setSelectedCategory]=useState("");const [selectedBrand,setSelectedBrand]=useState("");const [selectedUnit,setSelectedUnit]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [notice,setNotice]=useState("");
